window.LAWS=[{"id": "preambule", "titre": "Préambule", "resume": "Articulation des normes et principes fondateurs", "sections": [{"titre": "", "articles": [{"id": "preambule", "num": "Préambule", "titre": "De l'articulation des normes et des principes fondateurs", "paras": ["Considérant que l'ordre juridique en la province de Bordeciel s'inscrit dans le cadre constitutionnel de l'Empire et respecte la hiérarchie des normes ;", "Considérant que la législation d'Estemarche s'articule en pleine harmonie avec les Leges Imperiales — au premier rang desquelles figurent le Corpus Juriscivilis Imperialis (CJI), le Codex Penitus Imperialis (CPI), le De Re Nobilitatis, le Corpus Proceduralis Imperialis (CPIr) ainsi que les Traités et Décrets impériaux —, garantissant ainsi la pleine conformité de la législation d'Estemarche au droit impérial et la sécurité juridique de ses actes ;", "Considérant qu'il appartient à la Châtellerie d'Estemarche de rassembler l'ensemble de ses textes fondamentaux et décrets d'application au sein d'un recueil unique pour en assurer la lisibilité, la clarté et l'efficacité opérationnelle sur le terrain ;", "Considérant la volonté de préserver le modèle légal nordique d'Estemarche, fondé sur l'honneur, le pragmatisme, le respect du patrimoine ancestral et l'autorité directe du seigneur territorial ;", "Considérant la nécessité d'assurer la stabilité et la pérennité du présent Codex lors de l'adoption de futures lois ou décrets, en prévoyant que tout ajout ultérieur s'insérera par voie d'extension par titre sans altérer la numérotation établie ;", "Considérant la règle coutumière d'Estemarche en vertu de laquelle tout différend ou litige entre citoyens et commerçants fait l'objet d'une demande d'audience directe devant le Jarl pour arbitrage souverain en son Palais des Rois ;", "Il est promulgué le présent Grand Codex d'Estemarche, qui dispose ce qui suit :"]}]}], "doc": "codex"}, {"id": "partie-i", "titre": "Partie I — Lois fondamentales", "resume": "Trône, Palais, forces armées, citoyenneté, magie, droit pénal", "sections": [{"titre": "Titre I — Du Trône, de la succession et de la régence", "articles": [{"id": "codex-i-1", "num": "Art. I.1", "titre": "De l'héritier du trône", "paras": ["Le titre honorifique de Lame du Trône, conféré par le Jarl au cours de son règne, désigne son détenteur comme héritier légitime du trône d'Estemarche. À la disparition, à l'abdication, à l'incapacité définitive ou à la déchéance régulière du Jarl prononcée selon les lois en vigueur, la Lame du Trône lui succède de plein droit, sous réserve de la prestation du serment d'allégeance et de la notification à la Chancellerie Impériale (De Re Nobilitatis, Art. 4 ; Décret relatif aux successions, Art. 2)."]}, {"id": "codex-i-2", "num": "Art. I.2", "titre": "De l'absence d'héritier désigné et du Thing", "paras": ["Si aucun individu ne porte le titre de Lame du Trône au moment où le trône devient vacant, un Thing est convoqué dans les plus brefs délais afin d'élire, à la majorité des voix, un nouveau Jarl parmi les citoyens d'Estemarche. Le Thing est composé des représentants suivants, chacun disposant d'une voix :", {"li": "Un représentant de chaque commerce reconnu d'Estemarche"}, {"li": "Chaque Porte-voix en exercice"}, {"li": "Le représentant de chaque clan reconnu d'Estemarche"}, {"li": "Chaque Prêtre de Cour en exercice"}, {"li": "Chaque titulaire d'un des Grands Offices d'Estemarche"}, {"li": "Chaque Thane d'Estemarche"}, "Le Thing constitue l'assemblée coutumière légitime habilitée à désigner le nouveau Jarl d'Estemarche. L'élu accède au trône et reçoit la noblesse territoriale après prestation du serment d'allégeance coutumier et notification à la Chancellerie Impériale pour enregistrement au Registre Unifié de la Noblesse (De Re Nobilitatis, Arts. 4 & 7)."]}, {"id": "codex-i-3", "num": "Art. I.3", "titre": "De la régence", "paras": ["Dans l'attente de la désignation d'un nouveau Jarl, les fonctions de régent reviennent de plein droit au Chancelier d'Estemarche. Il assure la continuité du gouvernement et exerce les prérogatives nécessaires, sans pouvoir modifier les lois fondamentales ni aliéner les droits de la Châtellerie, avec notification d'usage à la Chancellerie Impériale."]}, {"id": "codex-i-4", "num": "Art. I.4", "titre": "De la légitimité et de la désignation de l'héritier", "paras": ["Le Jarl succédant en qualité de Lame du Trône ou élu par le Thing jouit de l'ensemble des droits, devoirs et prérogatives rattachés à la dignité de Jarl d'Estemarche. Dès son investiture officielle, il lui appartient, s'il le souhaite, de désigner une nouvelle Lame du Trône par acte officiel notifié à la Cour et transmis à la Chancellerie Impériale."]}]}, {"titre": "Titre II — Du Palais des Rois, de la Cour et des audiences", "articles": [{"id": "codex-ii-1", "num": "Art. II.1", "titre": "Du caractère sacré et de l'autorité du Palais des Rois", "paras": ["Le Palais des Rois constitue le siège officiel du gouvernement territorial de la Châtellerie d'Estemarche et le haut lieu de l'autorité du Jarl. Il est placé sous la protection conjointe du Jarl, de sa Garde et de l'Empire. Toute personne pénétrant dans son enceinte est tenue d'observer le respect dû au Jarl, aux institutions d'Estemarche, à l'Empire et à leurs représentants légitimes."]}, {"id": "codex-ii-2", "num": "Art. II.2", "titre": "De l'accès au Palais des Rois", "paras": ["L'accès au Palais des Rois est libre durant les heures d'ouverture fixées par les institutions de la Châtellerie. Les appartements privés, salles du conseil, archives, armureries et autres lieux réservés ne sont accessibles qu'aux personnes expressément autorisées par le Jarl ou sa Cour."]}, {"id": "codex-ii-3", "num": "Art. II.3", "titre": "De la conduite au sein du Palais des Rois", "paras": ["Toute personne présente dans le Palais doit adopter une conduite digne et respectueuse. Sont notamment interdits :", {"li": "1. Le port ostentatoire d'armes dégainées"}, {"li": "2. Le racolage, la sollicitation commerciale ou la vente non expressément autorisée par le Jarl ou sa Cour"}, {"li": "3. Le fait de courir au sein du Palais, sauf cas d'urgence, d'alerte ou exercice de fonctions officielles"}, {"li": "4. Le port de tout casque, heaume, capuchon ou masque dissimulant le visage, à l'exception des membres des forces de sécurité régulières dans l'exercice de leurs fonctions"}, {"li": "5. Les altercations, insultes, menaces, actes de violence ou de vandalisme"}, {"li": "6. Toute perturbation des audiences ou des travaux de la Cour"}, "Tout manquement aux règles de conduite ci-dessus expose son auteur à une expulsion immédiate par la Garde et à une amende de police de 250 à 500 septims OU l'exécution immédiate de 1 à 2 heures de travaux légers d'intérêt public OU 1 à 2 heures d'emprisonnement (CPIr, Art. 7 ; CJI, Art. 3)."]}, {"id": "codex-ii-4", "num": "Art. II.4", "titre": "De la protection de la Cour et du Trône", "paras": ["Constitue un crime contre la Châtellerie et contre l'ordre public toute tentative d'attentat, de complot, d'espionnage, de vol ou d'atteinte à l'intégrité du Jarl, des membres de sa Cour ou des biens du Palais, ainsi que le fait de s'asseoir de manière illégitime sur le Trône du Jarl ou d'en usurper les attributs. Ces infractions criminelles sont obligatoirement déférées devant le magistrat compétent (CPIr, Art. 11) et punies des peines prévues au Titre III du Corpus Juriscivilis Imperialis (travaux forcés, emprisonnement, bannissement ou peine capitale selon la gravité des faits)."]}, {"id": "codex-ii-5", "num": "Art. II.5", "titre": "Des audiences, requêtes et préséance", "paras": ["Tout sujet peut solliciter une audience auprès du Jarl ou de son administration afin d'exposer une requête, un litige ou une proposition. Les citoyens convoqués officiellement par le Jarl ou sa Cour bénéficient d'une priorité d'examen. Les membres de la noblesse reconnue jouissent de leur droit d'audience prioritaire conformément à l'Article 12 du De Re Nobilitatis. Les audiences peuvent être différées ou refusées pour des motifs motivés de sécurité du Palais ou de sauvegarde de l'ordre public."]}, {"id": "codex-ii-6", "num": "Art. II.6", "titre": "De l'autorité de la Garde du Palais", "paras": ["La Garde du Palais est investie du pouvoir de contrôler l'accès aux lieux, de procéder aux vérifications de sécurité nécessaires, de maintenir l'ordre et d'expulser toute personne troublant la tranquillité du Palais ou la paix de l'Empereur. Les injonctions légales données par la Garde doivent être immédiatement exécutées. Tout refus d'obtempérer est poursuivi conformément à l'Article 2 du Corpus Juriscivilis Imperialis, sans préjudice des protections accordées par les Leges Imperiales aux représentants impériaux dans l'exercice de leurs fonctions."]}, {"id": "codex-ii-7", "num": "Art. II.7", "titre": "Du respect et de la protection des institutions", "paras": ["Le respect constitue une valeur fondamentale d'Estemarche. Toute personne présente au Palais des Rois est tenue de faire preuve de déférence et de retenue envers le Jarl, la Cour, les représentants de la Châtellerie et de l'Empire. Toute attitude irrespectueuse, outrageante ou provocatrice envers les institutions est interdite. Tout manquement au présent article est sanctionné par la Garde par une amende de 500 septims OU l'exécution immédiate de deux (2) heures de travaux légers d'intérêt public OU deux (2) heures d'emprisonnement, conformément à l'Article 3 du Corpus Juriscivilis Imperialis et à l'Article 7 du Corpus Proceduralis Imperialis. En cas de refus d'exécution ou de contestation, le prévenu est placé en rétention conservatoire pour une durée maximale de vingt-quatre (24) heures (CPIr, Art. 7-1) dans l'attente de sa comparution devant le magistrat. Si l'outrage vise un représentant impérial protégé au sens des Articles 1 et 2 du Codex Penitus Imperialis, les faits sont poursuivis conformément aux Articles 6 et 8 dudit Code."]}, {"id": "codex-ii-8", "num": "Art. II.8", "titre": "Du secret du Conseil et des Archives", "paras": ["Les délibérations de la Cour tenues à huis clos, les registres officiels de la Châtellerie et les archives conservées au Palais des Rois sont placés sous la sauvegarde directe du Chancelier et du Jarl. Toute soustraction, copie non autorisée, divulgation ou falsification de documents officiels du Palais est interdite et poursuivie comme délit majeur ou crime de vol, recel ou atteinte aux registres publics (CJI, Arts. 6, 7 & 8)."]}, {"id": "codex-ii-9", "num": "Art. II.9", "titre": "Des émissaires et délégations diplomatiques", "paras": ["Les émissaires, diplomates et représentants officiellement accrédités auprès du Jarl bénéficient de la protection du Palais des Rois durant leurs audiences et séjours officiels. Toute provocation ou atteinte commise à leur encontre dans l'enceinte du Palais est poursuivie selon la gravité des faits au titre du trouble à l'ordre public ou des traités impériaux en vigueur."]}]}, {"titre": "Titre III — Des forces armées et de la défense du territoire", "articles": [{"id": "codex-iii-1", "num": "Art. III.1", "titre": "De l'armure officielle de la Châtellerie", "paras": ["L'armure officielle de la Châtellerie d'Estemarche est la tenue attribuée à ses forces régulières. Tout port, usage ou présentation non autorisé de cette armure par une personne ne disposant pas de l'habilitation requise constitue un délit d'usurpation de fonction officielle conformément à l'Article 1 du Corpus Juriscivilis Imperialis. L'usurpation d'armure officielle constitue un délit d'usurpation de fonction (CJI, Art. 1), sanctionné par la Garde par une amende de 1000 septims OU l'exécution immédiate de quatre (4) heures de travaux d'intérêt public OU quatre (4) heures d'emprisonnement, assortie de la restitution immédiate de l'armure (CPIr, Art. 7). En cas de contestation ou de refus d'exécution, le prévenu est placé en rétention conservatoire pour une durée maximale de vingt-quatre (24) heures (CPIr, Art. 7-1) dans l'attente de sa comparution devant le magistrat."]}, {"id": "codex-iii-2", "num": "Art. III.2", "titre": "De l'usage du Cor de guerre", "paras": ["L'usage du Cor de guerre est exclusivement réservé aux forces armées de la Châtellerie d'Estemarche et aux personnes munies d'une autorisation expresse de la Cour. Toute utilisation du Cor de guerre sans autorisation constitue une contravention d'atteinte à la paix publique conformément à l'Article 3 du Corpus Juriscivilis Imperialis. L'infraction constitue une atteinte à la tranquillité publique (CJI, Art. 3), passible d'une amende de 200 septims OU de l'exécution immédiate d'une (1) heure de travaux légers d'intérêt public OU d'une (1) heure d'emprisonnement (CPIr, Art. 7). En cas de refus d'exécution ou de contestation, le prévenu est placé en rétention conservatoire pour une durée maximale de vingt-quatre (24) heures (CPIr, Art. 7-1) devant le magistrat."]}, {"id": "codex-iii-3", "num": "Art. III.3", "titre": "Du passage des troupes et forces extérieures", "paras": ["Toute troupe armée supérieure à 10 hommes extérieure à la Châtellerie d'Estemarche pénétrant ou traversant le territoire d'Estemarche sans accord préalable de la Cour est réputée agir en violation de la paix territoriale et peut être déclarée force hostile par les autorités d'Estemarche. Le présent article ne s'applique ni à la Légion Impériale, ni aux forces de sécurité et administrateurs impériaux sous mandat direct (Codex Penitus Imperialis, Arts. 1 & 2), ni aux escortes officielles autorisées en vertu des Leges Imperiales ou des traités impériaux en vigueur."]}, {"id": "codex-iii-4", "num": "Art. III.4", "titre": "De l'autorité en matière de défense", "paras": ["La défense de la Châtellerie d'Estemarche relève exclusivement des autorités militaires compétentes. À ce titre, la Garde de Vendeaume, le Commandement de la Châtellerie et la Légion Impériale sont les seules autorités habilitées à organiser, diriger et conduire les opérations de défense du territoire de la Châtellerie d'Estemarche."]}, {"id": "codex-iii-5", "num": "Art. III.5", "titre": "De l'interdiction des milices non autorisées", "paras": ["La création, le recrutement, le maintien ou le commandement de toute milice privée, armée clanique ou groupe paramilitaire non déclaré auprès de la Cour et non placé sous l'autorité du Jarl est strictement interdit sur le territoire d'Estemarche. Tout manquement constitue un délit majeur ou un crime d'usurpation de fonction et d'exercice illégal de la force publique (CJI, Arts. 1 & 17 ; CPI, Art. 11)."]}]}, {"titre": "Titre IV — De la citoyenneté, des droits civils et de l'Ost civique", "articles": [{"id": "codex-iv-1", "num": "Art. IV.1", "titre": "Du citoyen recensé", "paras": ["Est reconnu comme citoyen recensé toute personne inscrite au registre officiel de la Châtellerie."], "chap": "Chapitre I — De la reconnaissance civique et des devoirs"}, {"id": "codex-iv-2", "num": "Art. IV.2", "titre": "De l'entraide", "paras": ["Lorsque l'autorité publique appelle la population à porter secours à la Châtellerie, tout citoyen est tenu d'apporter son concours dans la mesure de ses capacités."], "chap": "Chapitre I — De la reconnaissance civique et des devoirs"}, {"id": "codex-iv-3", "num": "Art. IV.3", "titre": "De l'impôt censitaire et de l'octroi de la citoyenneté", "paras": ["La qualité de citoyen recensé de la Châtellerie est acquise par l'inscription au registre officiel des citoyens et par le règlement de l'impôt censitaire fixé. L'inscription confère au citoyen l'ensemble des droits et obligations prévus par le présent Code ainsi que par les autres lois."], "chap": "Chapitre I — De la reconnaissance civique et des devoirs"}, {"id": "codex-iv-4", "num": "Art. IV.4", "titre": "De la force obligatoire et de l'exécution", "paras": ["est tenu de s'acquitter régulièrement de l'impôt censitaire dans les délais fixés par la Châtellerie. En cas de retard de paiement, une période de grâce pouvant aller jusqu'à une semaine peut être accordée lorsque le citoyen justifie d'une implication active dans la vie de la Châtellerie ou d'un motif légitime. À l'issue de ce délai, le citoyen demeure tenu de régulariser l'ensemble des sommes dues afin de conserver sa qualité de citoyen recensé."], "chap": "Chapitre I — De la reconnaissance civique et des devoirs"}, {"id": "codex-iv-5", "num": "Art. IV.5", "titre": "De la radiation du registre des citoyens", "paras": ["Tout citoyen qui, sans justification reconnue, omet de s'acquitter de son impôt pendant une période prolongée d'une semaine pourra être radié du registre officiel des citoyens. La radiation entraîne la perte immédiate de l'ensemble des droits attachés à la citoyenneté. Toute nouvelle demande de citoyenneté demeure subordonnée au règlement des sommes demeurées impayées."], "chap": "Chapitre I — De la reconnaissance civique et des devoirs"}, {"id": "codex-iv-6", "num": "Art. IV.6", "titre": "Du serment de fidélité", "paras": ["Tout citoyen recensé reconnaît l'autorité du Jarl, des lois de la Châtellerie, s'engage à respecter les institutions d'Estemarche ainsi que la primauté des lois de l'Empire. Nul ne peut se prévaloir de la qualité de citoyen tout en agissant volontairement contre les intérêts légitimes de la Châtellerie ou de l'Empire."], "chap": "Chapitre I — De la reconnaissance civique et des devoirs"}, {"id": "codex-iv-7", "num": "Art. IV.7", "titre": "Du droit de propriété", "paras": ["Tout citoyen recensé peut acquérir une maison, un stockage (tonneaux ou coffres) ou un local commercial situé sur le territoire de la Châtellerie d'Estemarche, conformément aux lois et règlements en vigueur."], "chap": "Chapitre II — Des droits citoyens et de l'audience du Jarl"}, {"id": "codex-iv-8", "num": "Art. IV.8", "titre": "Du droit de chasse", "paras": ["Les citoyens recensés peuvent pratiquer la chasse sur les terres relevant de la Châtellerie d'Estemarche dans le respect des éventuelles restrictions décidées par la Cour. La chasse ne doit ni compromettre la sécurité publique, ni porter atteinte aux intérêts de la Châtellerie."], "chap": "Chapitre II — Des droits citoyens et de l'audience du Jarl"}, {"id": "codex-iv-9", "num": "Art. IV.9", "titre": "Du droit de récolte du sel", "paras": ["Les citoyens recensés et autorisés par la Mine du Sel sont autorisés à récolter le sel provenant des marais salants, côtes ou autres sites autorisés par la Châtellerie. Cette activité peut faire l'objet de limitations destinées à préserver les ressources naturelles ou à répondre aux besoins stratégiques d'Estemarche."], "chap": "Chapitre II — Des droits citoyens et de l'audience du Jarl"}, {"id": "codex-iv-10", "num": "Art. IV.10", "titre": "Du droit d'accès au marché et des audiences du Jarl", "paras": ["Tout citoyen recensé peut librement exercer une activité commerciale à la Châtellerie. Il bénéficie d'un accès prioritaire aux étals et emplacements commerciaux prévus à cet effet, en échange du paiement requis. Spécificité coutumière de Vendeaume : Pour tout différend ou litige d'ordre civil ou commercial survenant entre citoyens ou entre commerçants, les parties sont tenues de former une demande d'audience directe devant le Jarl en son Palais des Rois. Le Jarl tranche et arbitre le litige en personne, selon l'équité, l'honneur nordique et les coutumes de la Châtellerie."], "chap": "Chapitre II — Des droits citoyens et de l'audience du Jarl"}, {"id": "codex-iv-11", "num": "Art. IV.11", "titre": "Du droit de minage", "paras": ["Tout citoyen recensé peut exploiter les ressources minières situées sur le territoire de la Châtellerie, dans le respect des concessions accordées, des règlements de sécurité et des intérêts de la Cour. Le minage et l'exploitation du sel sont exclusivement autorisés sur accord préalable du propriétaire de la mine concernée. Nul ne peut extraire, exploiter ou prélever du sel sur une mine sans l'autorisation expresse de son propriétaire."], "chap": "Chapitre II — Des droits citoyens et de l'audience du Jarl"}, {"id": "codex-iv-12", "num": "Art. IV.12", "titre": "Du droit de sépulture", "paras": ["Tout citoyen recensé a droit à une sépulture digne selon les traditions reconnues par la Châtellerie, sauf décision contraire de la justice."], "chap": "Chapitre II — Des droits citoyens et de l'audience du Jarl"}, {"id": "codex-iv-13", "num": "Art. IV.13", "titre": "De l'Ost civique", "paras": ["L'Ost civique est une force de soutien composée de citoyens recensés qui choisissent volontairement de se mettre au service de la Châtellerie d'Estemarche lorsque les circonstances l'exigent."], "chap": "Chapitre III — De l'Ost civique"}, {"id": "codex-iv-14", "num": "Art. IV.14", "titre": "De la levée de l'Ost", "paras": ["Le Jarl, son Régent ou la Cour peuvent appeler les citoyens recensés à rejoindre l'Ost civique en cas de guerre, de catastrophe, de menace surnaturelle, de troubles majeurs ou de toute autre situation nécessitant un renfort exceptionnel. Cet appel repose sur le volontariat des citoyens."], "chap": "Chapitre III — De l'Ost civique"}, {"id": "codex-iv-15", "num": "Art. IV.15", "titre": "Des missions de l'Ost", "paras": ["Les membres de l'Ost civique peuvent être chargés d'assurer des missions de surveillance, de protection des infrastructures, d'escorte, de ravitaillement, de secours aux populations, de soutien logistique ou, lorsque la situation l'impose, de participer à la défense de la Châtellerie."], "chap": "Chapitre III — De l'Ost civique"}, {"id": "codex-iv-16", "num": "Art. IV.16", "titre": "De l'encadrement", "paras": ["Les membres de l'Ost civique agissent sous l'autorité de la Cour, de la Garde d'Estemarche ou de toute autorité désignée par le Jarl. Ils sont tenus de respecter les ordres légitimes qui leur sont donnés pendant toute la durée de leur engagement."], "chap": "Chapitre III — De l'Ost civique"}, {"id": "codex-iv-17", "num": "Art. IV.17", "titre": "De la reconnaissance", "paras": ["La Châtellerie reconnaît et honore l'engagement des citoyens ayant servi au sein de l'Ost civique. Le Jarl peut leur accorder des distinctions, des récompenses, des exemptions ou toute autre marque de reconnaissance en considération des services rendus à Estemarche."], "chap": "Chapitre III — De l'Ost civique"}, {"id": "codex-iv-18", "num": "Art. IV.18", "titre": "Du caractère défensif et civil de l'Ost", "paras": ["L'Ost civique constitue une force de réserve et de secours civil à caractère exclusivement territorial et défensif. Sa mobilisation, fondée sur le volontariat citoyen pour la protection des populations, des infrastructures ou en cas de sinistre, ne constitue en aucun cas un acte d'hostilité envers l'Empire et s'exerce dans le strict respect de la paix publique."], "chap": "Chapitre III — De l'Ost civique"}]}, {"titre": "Titre V — Des arts magiques et des enchanteurs", "articles": [{"id": "codex-v-1", "num": "Art. V.1", "titre": "De la reconnaissance de l'Académie de Fortdhiver", "paras": ["La Châtellerie d'Estemarche reconnaît l'Académie de Fortdhiver comme l'institution académique provinciale compétente pour dispenser un enseignement officiel des arts magiques et délivrer les diplômes attestant de leur maîtrise, sans préjudice des titres, qualifications et mandats reconnus par les institutions de l'Empire."]}, {"id": "codex-v-2", "num": "Art. V.2", "titre": "Du port et de l'usage des bâtons de magie", "paras": ["Le port, la détention apparente et l'utilisation de bâtons de magie hors du domicile sont interdits sur l'ensemble du territoire d'Estemarche et dans la cité de Vendeaume pour toute personne ne pouvant justifier soit d'un diplôme reconnu de l'Académie de Fortdhiver, soit d'une licence de port régulière délivrée conformément au Décret Impérial relatif aux bâtons de magie. La Garde de Vendeaume est habilitée à procéder à la saisie conservatoire de tout bâton porté sans titre valide. Tout manquement constitue un usage non autorisé réprimé par l'Article 11 du Corpus Juriscivilis Imperialis. Le contrevenant est passible d'une amende délictuelle de 2 000 septims OU de l'exécution immédiate de huit (8) heures de corvée d'intérêt public OU de huit (8) heures d'emprisonnement sous la surveillance de la garnison (CPIr, Art. 7 ; CJI, Art. 11)."]}, {"id": "codex-v-3", "num": "Art. V.3", "titre": "Du prix réglementé des gemmes spirituelles remplies", "paras": ["Afin de prévenir la spéculation sur les ressources magiques ordinaires, le prix de vente maximal d'une gemme spirituelle blanche ou ordinaire remplie est fixé à 50 septims l'unité sur l'ensemble du territoire d'Estemarche. Le présent article ne s'applique en aucun cas aux gemmes spirituelles noires, dont la possession, la capture d'âme humaine et le commerce sont strictement interdits et poursuivis comme délit grave ou crime au titre de l'Article 11 du Corpus Juriscivilis Imperialis. Toute vente d'une gemme ordinaire remplie à un prix supérieur au tarif réglementé constitue une infraction aux règles du marché local. Le contrevenant est passible d'une amende de 500 septims OU de l'exécution immédiate de deux (2) heures de travaux légers d'intérêt public OU de deux (2) heures d'emprisonnement (CPIr, Art. 7), assortie de la confiscation de la marchandise."]}, {"id": "codex-v-4", "num": "Art. V.4", "titre": "De l'enregistrement des enchanteurs", "paras": ["Toute personne exerçant ou souhaitant exercer l'activité d'enchanteur sur le territoire d'Estemarche est tenue de se faire enregistrer auprès de la Cour préalablement à l'exercice de son art, afin d'assurer la traçabilité des enchantements et le respect des lois relatives aux arts magiques. L'exercice de l'activité d'enchanteur sans enregistrement préalable constitue un délit d'exercice non autorisé d'une profession réglementée (CJI, Art. 1). L'infraction est passible d'une amende de 1 000 septims ou de l'exécution immédiate de quatre (4) heures de travaux d'intérêt public OU de quatre (4) heures d'emprisonnement sous la surveillance de la garnison (CPIr, Art. 7). En cas de contestation ou de récidive, le contrevenant est placé en rétention conservatoire (CPIr, Art. 7-1) en vue de sa présentation au magistrat."]}, {"id": "codex-v-5", "num": "Art. V.5", "titre": "De la prohibition de la nécromancie et des rituels profanes", "paras": ["La pratique de la nécromancie, l'invocation d'entités daedriques hostiles, la profanation de sépultures et l'usage de la magie à des fins de contrainte ou d'atteinte physique ou mentale à autrui sont strictement interdits sur l'ensemble du territoire d'Estemarche. Tout contrevenant est immédiatement appréhendé, placé en rétention conservatoire (24h max, CPIr, Art. 7-1) et déféré devant le magistrat pour délit grave ou crime au sens des Articles 9, 10, 11 et 16 du Corpus Juriscivilis Imperialis."]}, {"id": "codex-v-6", "num": "Art. V.6", "titre": "Des artefacts dangereux et armes éthérées", "paras": ["La création, la détention et le commerce d'armes dites éthérées ou d'artefacts magiques instables présentant un danger manifeste pour la sécurité publique sont interdits conformément au Décret Impérial relatif aux armes éthérées. Tout artefact de cette nature découvert sur le territoire d'Estemarche doit être immédiatement déclaré à la Cour et mis sous scellés par la Garde dans l'attente d'une expertise officielle."]}]}, {"titre": "Titre VI — De l'application territoriale du droit pénal impérial", "articles": [{"id": "codex-vi-1", "num": "Art. VI.1", "titre": "Du principe d'application directe et dynamique du Droit Pénal Impérial", "paras": ["L'ensemble des contraventions, délits et crimes de droit commun commis sur le territoire d'Estemarche sont qualifiés, poursuivis et réprimés conformément aux dispositions du Corpus Juriscivilis Imperialis (CJI) et du Codex Penitus Imperialis (CPI) en vigueur. Toute modification, révision ou adjonction apportée à la législation pénale impériale par la Chancellerie Impériale s'applique de plein droit et immédiatement sur le territoire d'Estemarche, garantissant ainsi l'harmonie constante entre le droit territorial et le droit souverain de l'Empire sans qu'une révision du présent Codex ne soit requise."]}, {"id": "codex-vi-2", "num": "Art. VI.2", "titre": "Du barème d'exécution locale des peines (Grille d'Équivalence Unifiée)", "paras": ["Les peines de droit commun prévues par le Corpus Juriscivilis Imperialis sont exécutées sur le territoire d'Estemarche selon la Grille d'Équivalence Unifiée des Peines, en vertu de l'habilitation expresse accordée par la Chancellerie Impériale. La sanction encourue pour toute contravention ou délit simple est fixée selon la formule tri-partite suivante : le montant en septims OU la durée en heures de travaux d'intérêt public / corvée OU la durée en heures d'emprisonnement directe (la durée d'emprisonnement étant strictement égale à celle des travaux) (CPIr, Art. 7) :", {"li": "1. CONTRAVENTION : (Amende de 200 à 250 septims) : Équivalent à une (1) heure de travaux légers OU une (1) heure d'emprisonnement."}, {"li": "2. CONTRAVENTION SUPÉRIEURE : (Amende de 500 septims) : Équivalent à deux (2) heures de travaux légers OU deux (2) heures d'emprisonnement."}, {"li": "3. DÉLIT MINEUR : (Amende de 1 000 septims) : Équivalent à quatre (4) heures de travaux d'intérêt public OU quatre (4) heures d'emprisonnement."}, {"li": "4. DÉLIT MAJEUR : (Amende de 2 000 à 2 500 septims) : Équivalent à huit (8) à dix (10) heures de corvée OU huit (8) à dix (10) heures d'emprisonnement."}]}, {"id": "codex-vi-3", "num": "Art. VI.3", "titre": "Des prérogatives de la Garde et des peines d'emprisonnement en heures", "paras": ["Sur la voie publique, les membres de la Garde d'Estemarche veillent à l'application des lois et procèdent à la constatation des infractions. Pour toute contravention ou délit simple de droit commun, la Garde notifie la sanction selon l'option tri-partite accordée au territoire (amende en septims, corvée en heures ou emprisonnement direct en heures de durée identique). En application des directives de la Chancellerie Impériale, l'emprisonnement pour des durées courtes exprimées en heures est pleinement autorisé et exécuté dans les cellules du poste de la Garde. En cas de refus d'exécution, de contestation ou de faits qualifiés de crime, la Garde procède à l'interpellation du prévenu et à son placement en rétention conservatoire pour une durée maximale de vingt-quatre (24) heures (CPIr, Art. 7-1) aux fins de présentation immédiate devant le magistrat. La Garde procède systématiquement à la saisie conservatoire des objets, armes, produits ou substances illicites (CPIr, Art. 5)."]}, {"id": "codex-vi-4", "num": "Art. VI.4", "titre": "De la répartition des compétences judiciaires et du déféré des crimes", "paras": ["Les différends et litiges d'ordre civil, commercial ou coutumier entre citoyens relèvent de la procédure d'arbitrage par demande d'audience directe devant le Jarl en son Palais des Rois (Art. IV.10). Les infractions pénales qualifiées de crime au sens du Corpus Juriscivilis Imperialis (notamment le meurtre, l'assassinat, la séquestration, les cultes daedriques coercitifs, la profanation grave, l'évasion, l'usurpation du Trône ou les crimes avec circonstances aggravantes) relèvent de la compétence exclusive du magistrat judiciaire (CPIr, Art. 11), seul habilité à prononcer les peines criminelles prévues par la loi impériale (emprisonnement judiciaire, travaux forcés, bannissement ou peine capitale)."]}]}], "doc": "codex"}, {"id": "partie-ii", "titre": "Partie II — Décrets et règlements", "resume": "Main d'Argent, mine de Brûlevapeur, patrimoine et géants", "sections": [{"titre": "Titre VII — Du contrôle des équipements de la Main d'Argent", "articles": [{"id": "codex-vii-1", "num": "Art. VII.1", "titre": "De la détention des armes de la Main d'Argent", "paras": ["Les armes, armures et équipements portant les poinçons de la Main d'Argent ou appartenant à celle-ci sont réputés être la propriété de cette dernière. Leur détention sur le territoire d'Estemarche est soumise à autorisation en l'absence d'un titre de propriété valide, délivré ou reconnu par la Main d'Argent. À défaut, l'équipement devra être déclaré comme irrégulièrement détenu et remis aux autorités compétentes."]}, {"id": "codex-vii-2", "num": "Art. VII.2", "titre": "De la cession, commerce et de la possession", "paras": ["Nul ne pourra vendre, céder, transmettre ou acquérir une arme, une armure ou tout autre équipement appartenant à la Main d'Argent sans l'autorisation préalable de celle-ci. Toute transaction réalisée sans cette autorisation sera considérée comme irrégulière et ne pourra conférer aucun droit de propriété à l'acquéreur."]}, {"id": "codex-vii-3", "num": "Art. VII.3", "titre": "De la saisie", "paras": ["Tout équipement de la Main d'Argent détenu sans autorisation ou sans titre de propriété valide pourra faire l'objet d'une saisie immédiate par la garnison ou toute autorité dûment mandatée par la Châtellerie. Les biens saisis seront conservés par les autorités compétentes jusqu'à leur restitution."]}, {"id": "codex-vii-4", "num": "Art. VII.4", "titre": "Des réquisitions et des sanctions", "paras": ["La Châtellerie d'Estemarche est autorisée à identifier, réquisitionner et récupérer tout équipement appartenant à la Main d'Argent dont la détention n'est pas dûment justifiée. Toute personne reconnue coupable de dissimulation, de commerce ou de détention frauduleuse d'un tel équipement commet un délit de vol ou de recel d'objet sous licence (CJI, Arts. 6 & 7, susceptible d'être qualifié de [CRIME] sous la juridiction impériale). L'auteur est passible d'une amende délictuelle de 500 à 2 000 septims OU de l'exécution immédiate de deux (2) à huit (8) heures de corvée d'intérêt public OU de deux (2) à huit (8) heures d'emprisonnement sous la surveillance de la garnison, assortie de la saisie définitive des biens (CPIr, Art. 7 ; CJI, Arts. 6 & 7). En cas de contestation ou de refus d'exécution, le prévenu est placé en rétention conservatoire pour une durée maximale de vingt-quatre (24) heures (CPIr, Art. 7-1) dans l'attente de sa comparution devant le magistrat compétent."]}, {"id": "codex-vii-5", "num": "Art. VII.5", "titre": "Du délai de restitution", "paras": ["Les équipements acquis antérieurement à l'entrée en vigueur du présent décret ne bénéficient d'aucune exception. Leur détenteur devra en justifier la provenance ou les remettre soit à la Main d'Argent, soit à la garnison. Toute personne détenant irrégulièrement un équipement de la Main d'Argent sur le territoire d'Estemarche, sans autorisation, dispose d'un délai de 5 jours à compter de la promulgation du présent décret pour le déclarer et le remettre à la Main d'Argent. Passé ce délai, toute détention sera présumée volontaire."]}, {"id": "codex-vii-6", "num": "Art. VII.6", "titre": "De l'entrée en vigueur", "paras": ["Le présent décret entre en vigueur dès sa promulgation sur l'ensemble du territoire d'Estemarche. Nul ne pourra se prévaloir de son ignorance."]}]}, {"titre": "Titre VIII — De l'exploitation et de la protection de la mine de Brûlevapeur", "articles": [{"id": "codex-viii-1", "num": "Art. VIII.1", "titre": "De la propriété de la mine de Brûlevapeur", "paras": ["La mine de Brûlevapeur constitue une propriété privée et exclusive de la famille Longue-Braise, dont la propriété et les droits d'exploitation sont attachés à ladite lignée. À ce titre, l'ensemble de ses galeries, installations, équipements, fours, réserves, concessions et ressources minières relève de la propriété de la famille Longue-Braise. En raison de son importance stratégique, économique et industrielle pour Estemarche et la province de Bordeciel, la mine de Brûlevapeur est reconnue comme une exploitation d'intérêt majeur, dont la préservation et la sécurité relèvent également de l'autorité de la Châtellerie. La Châtellerie est habilitée à en assurer la protection administrative et sécuritaire par la surveillance de ses accès, la prévention des intrusions et l'intervention de ses forces lorsque la sécurité de la mine ou les intérêts légitimes de ses propriétaires sont menacés, sans constituer ni transfert ni remise en cause de la propriété privée."]}, {"id": "codex-viii-2", "num": "Art. VIII.2", "titre": "De l'accès et de l'autorisation d'exploitation", "paras": ["L'accès à la mine est strictement réglementé et réservé aux personnes dûment autorisées par les Longue-Braise ou toute personne mandatée à cet effet. Nul ne peut pénétrer dans l'enceinte de la mine, exploiter ses ressources, extraire de la malachite, utiliser ses installations ou y entreposer des biens sans l'autorisation préalable du propriétaire ou de son représentant dûment habilité."]}, {"id": "codex-viii-3", "num": "Art. VIII.3", "titre": "De l'introduction illégale, du pillage et des sanctions", "paras": ["Toute personne s'introduisant sans autorisation dans la mine de Brûlevapeur commet une intrusion sanctionnée au titre de l'Article 4 du Corpus Juriscivilis Imperialis, passible d'une amende de 500 septims OU 2 heures de travaux légers OU 2 heures d'emprisonnement (CPIr, Art. 7). L'extraction clandestine, le pillage de malachite, le vol ou la dégradation de matériel constituent des délits majeurs ou crimes de vol et de recel (CJI, Arts. 6, 7 & 8). La Garde procède à l'interpellation immédiate du contrevenant et à la saisie conservatoire des ressources et équipements (CPIr, Art. 5). En cas de contestation, de vol de minerai ou de circonstances aggravantes (usage d'armes, de magie ou fait commis en réunion), le prévenu est placé en rétention conservatoire (CPIr, Art. 7-1) et déféré devant le magistrat compétent (CPIr, Art. 11), lequel fixe le montant des réparations civiles dues à la famille Longue-Braise (pouvant atteindre 2 500 septims ou plus) ainsi que les peines pénales applicables."]}]}, {"titre": "Titre IX — De la préservation du patrimoine nordique et des géants", "articles": [{"id": "codex-ix-1", "num": "Art. IX.1", "titre": "De la préservation du patrimoine nordique", "paras": ["Le présent titre a pour objet d'assurer la protection, la conservation, la restauration et la transmission du patrimoine historique, culturel et religieux nordique présent sur le territoire d'Estemarche. Sont considérés comme faisant partie du patrimoine nordique : les tombes et cryptes anciennes, les ruines nordiques, les palais, forteresses, murailles et tours historiques, les temples et sanctuaires consacrés aux Divins ou aux anciens cultes nordiques reconnus, les statues, pierres runiques, stèles, autels et monuments, les manuscrits, archives, cartes et ouvrages historiques, les armes, armures, reliques et artefacts présentant un intérêt historique, ainsi que toute œuvre ou construction reconnue par décret."]}, {"id": "codex-ix-2", "num": "Art. IX.2", "titre": "Des sites nordiques protégés", "paras": ["La Cour, après avis des érudits, du Jarl ou de toute autorité compétente, peut classer un monument ou un site comme Patrimoine Nordique Protégé. Tout bien ainsi classé bénéficie d'une protection particulière. Les sites actuellement protégés en Estemarche sont :", {"li": "Tertre d'Ygnol"}, {"li": "Ansilvund"}, {"li": "Tombeau d'Hillgrund"}, {"li": "Sanctuaire du Primarbor"}, {"li": "Crête de l'ossuaire."}]}, {"id": "codex-ix-3", "num": "Art. IX.3", "titre": "Des fouilles et autorisations archéologiques", "paras": ["Toute expédition ou fouille archéologique sur le territoire d'Estemarche doit faire l'objet d'une autorisation préalable délivrée par les Grandes Archives de Bordeciel, dont le siège est établi à Vendeaume au Hall des Reliques (Décret impérial sur les recherches archéologiques, Arts. 1 & 3). Les découvertes majeures sont classées au Patrimoine Nordique Inaliénable et conservées sous la garde des Grandes Archives de Vendeaume pour le compte de la Châtellerie et de Bordeciel."]}, {"id": "codex-ix-4", "num": "Art. IX.4", "titre": "De la Cité des Rois", "paras": ["La cité de Vendeaume, en raison de son ancienneté, de son importance dans l'histoire de Bordeciel et des découvertes archéologiques réalisées en son sein, est reconnue comme Cité historique protégée. À ce titre, l'ensemble de ses monuments, fortifications, souterrains, vestiges, bâtiments anciens et sites présentant un intérêt historique ou culturel bénéficie d'une protection particulière. Toute découverte réalisée dans les souterrains, fondations ou environs de Vendeaume doit être immédiatement déclarée aux autorités de la Châtellerie. Aucun objet ne pourra être déplacé, vendu, détruit ou dissimulé sans autorisation."]}, {"id": "codex-ix-5", "num": "Art. IX.5", "titre": "Du Grand Registre du Patrimoine Nordique", "paras": ["Les découvertes présentant un intérêt exceptionnel pour l'histoire de Bordeciel sont classées comme Reliques historiques majeures. Ce classement entraîne leur protection absolue et leur inscription obligatoire au Grand Registre du Patrimoine Nordique, conservé par les Grandes Archives de Bordeciel à Vendeaume (Décret archéologique impérial, Art. 5)."]}, {"id": "codex-ix-6", "num": "Art. IX.6", "titre": "Des travaux et aménagements", "paras": ["Tout projet de construction, de rénovation ou d'aménagement susceptible d'affecter les vestiges historiques de Vendeaume devra faire l'objet d'une étude préalable menée par les autorités compétentes. Lorsque des vestiges sont mis au jour, les travaux pourront être suspendus jusqu'à la réalisation des investigations nécessaires à leur préservation."]}, {"id": "codex-ix-7", "num": "Art. IX.7", "titre": "De la mémoire", "paras": ["Vendeaume est reconnue comme l'un des principaux gardiens de la mémoire des anciens Nordiques. La Cour veillera à la préservation de son héritage, à la restauration de ses monuments et à la transmission de son histoire aux générations futures, afin que nul n'oublie les exploits des anciens héros ni les fondements sur lesquels repose Bordeciel."]}, {"id": "codex-ix-8", "num": "Art. IX.8", "titre": "De la reconnaissance des géants", "paras": ["Les géants de Bordeciel sont reconnus comme des créatures ancestrales participant à l'équilibre des terres nordiques et au patrimoine vivant. Leur présence dans les plaines, montagnes et territoires traditionnels doit être préservée lorsque celle-ci ne constitue pas une menace directe pour les populations ou les infrastructures."]}, {"id": "codex-ix-9", "num": "Art. IX.9", "titre": "De l'interdiction de la chasse de géant", "paras": ["La chasse, la traque, la capture ou la mise à mort d'un géant sont interdites sur l'ensemble des terres relevant d'Estemarche. Cette interdiction s'applique également à toute tentative de prélèvement de défenses, d'os, de peaux ou de toute autre partie provenant d'un géant abattu illégalement."]}, {"id": "codex-ix-10", "num": "Art. IX.10", "titre": "De l'autorisation de la chasse", "paras": ["Par exception, une autorisation de chasse peut être délivrée lorsque :", {"li": "1. Un géant représente une menace avérée pour une cité, un village, une route commerciale ou des exploitations agricoles"}, {"li": "2. Une opération de défense du territoire est ordonnée par la Cour"}, {"li": "3. Une mission scientifique, militaire ou de régulation est jugée nécessaire par les autorités compétentes"}, "Dans ces cas, la chasse ne peut être menée que par la Garde de Vendeaume, les forces militaires reconnues, ou les chasseurs titulaires d'une licence spéciale de régulation des géants délivrée par la Cour."]}, {"id": "codex-ix-11", "num": "Art. IX.11", "titre": "Du principe général de sanction", "paras": ["Toute violation des dispositions du présent titre constitue une atteinte au patrimoine, à l'histoire ou aux intérêts de la Châtellerie et expose son auteur à des sanctions administratives, civiles et pénales, sans préjudice des poursuites pouvant être engagées en vertu des autres lois en vigueur."]}, {"id": "codex-ix-12", "num": "Art. IX.12", "titre": "Des manquements et sanctions", "paras": ["Les atteintes volontaires portées aux sanctuaires, sépultures, stèles sacrées ou lieux de culte protégés constituent des délits de profanation au sens de l'Article 10 du Corpus Juriscivilis Imperialis. Les fouilles clandestines, destructions de vestiges ou chasses non autorisées de géants constituent des délits d'atteinte au patrimoine ou de braconnage (CJI, Arts. 4 & 6). L'auteur d'un manquement est passible d'une amende délictuelle de 500 à 2 500 septims OU de l'exécution de deux (2) à dix (10) heures de corvée d'intérêt public OU de deux (2) à dix (10) heures d'emprisonnement sous la surveillance de la garnison (CPIr, Art. 7 ; CJI, Arts. 4 & 6)."]}, {"id": "codex-ix-13", "num": "Art. IX.13", "titre": "Des artefacts dangereux ou occultes mis au jour", "paras": ["Tout objet ou artefact mis au jour lors de fouilles et présentant des propriétés occultes, nécromantiques, daedriques ou instables doit être immédiatement déclaré aux Grandes Archives de Vendeaume et mis sous scellés de sécurité par la Garde (Décret archéologique impérial, Art. 8). Son étude ou son expérimentation non autorisée est interdite et poursuivie comme délit d'usage de magie non autorisé (CJI, Art. 11)."]}]}], "doc": "codex"}, {"id": "partie-iii", "titre": "Partie III — Traités et engagements", "resume": "Vassalité, Traité de l'Or Blanc, pactes inter-châtelleries", "sections": [{"titre": "", "articles": [{"id": "partie-iii-1", "num": "§ 1", "titre": "Rappel de vassalité et d'allégeance", "paras": ["Les engagements souscrits par la Châtellerie d'Estemarche envers la Couronne Impériale de Tamriel priment sur l'ensemble des règles de droit local."]}, {"id": "partie-iii-2", "num": "§ 2", "titre": "Clauses du Traité de l'Or Blanc (Concordat)", "paras": ["Respect des zones neutralisées, protection des émissaires diplomatiques accrédités et prohibition des cultes interdits par les accords de paix impériaux."]}, {"id": "partie-iii-3", "num": "§ 3", "titre": "Pactes inter-châtelleries", "paras": ["Respect des frontières territoriales avec les Châtelleries voisines de Fortdhiver, du Clos et de la Brèche, régulation des droits de passage et entraide judiciaire."]}]}], "doc": "codex"}, {"id": "partie-iv", "titre": "Partie IV — Dispositions finales", "resume": "Abrogation, entrée en vigueur, force obligatoire", "sections": [{"titre": "", "articles": [{"id": "final-iv-1", "num": "Art. IV.1", "titre": "De l'abrogation des dispositions antérieures et de la substitution de plein droit", "paras": ["À compter de sa promulgation, sont et demeurent intégralement abrogés l'ensemble des anciens codes, décrets, ordonnances, arrêtés, règlements et coutumes territoriales d'Estemarche promulgués antérieurement et portant sur les matières régies par le présent Codex ou entrant en contradiction avec ses dispositions. Le présent Codex se substitue de plein droit et dans son intégralité à tous les textes territoriaux antérieurs."]}, {"id": "final-iv-2", "num": "Art. IV.2", "titre": "De l'entrée en vigueur de plein droit", "paras": ["Le présent Grand Codex entre en vigueur de plein droit et à effet immédiat dès sa promulgation officielle par le Jarl et son affichage aux lieux accoutumés de la cité de Vendeaume et du territoire d'Estemarche. Nul ne pourra se prévaloir de l'ignorance de ses dispositions."]}, {"id": "final-iv-3", "num": "Art. IV.3", "titre": "De la validité des actes et droits régulièrement acquis", "paras": ["L'abrogation prévue à l'Article IV.1 ne porte pas atteinte à la validité des décisions judiciaires devenues définitives, des contrats régulièrement formés, des titres de propriété légitimement enregistrés ni des concessions octroyées sous l'empire des réglementations antérieures."]}, {"id": "final-iv-4", "num": "Art. IV.4", "titre": "De la force obligatoire et de l'exécution", "paras": ["Mandat formel est donné au Chancelier d'Estemarche, au Capitaine de la Garde de Vendeaume, aux officiers de garnison ainsi qu'aux magistrats et juges territoriaux de veiller à la stricte application, à la diffusion et à l'exécution du présent Grand Codex."]}]}], "doc": "codex"}, {"id": "fiche-poche", "titre": "Fiche de poche du garde", "resume": "Aide-mémoire : procédure d'interpellation et rétention conservatoire", "sections": [{"titre": "Avertissement réglementaire", "articles": [{"id": "fiche-avert", "num": "Avert.", "titre": "Valeur du présent aide-mémoire", "paras": ["« Le présent aide-mémoire constitue un instrument de consultation et ne possède aucune valeur normative autonome. En cas de divergence, les dispositions du Grand Codex d'Estemarche et des Leges Imperiales prévalent. »"]}]}, {"titre": "Procédure générale d'interpellation en 6 étapes", "articles": [{"id": "fiche-e1", "num": "Étape 1", "titre": "Constater les faits", "paras": [{"li": "Observation directe : le garde identifie et consigne ce qu'il a personnellement observé en situation de flagrance ou lors d'un contrôle."}, {"li": "Triage de la preuve : distinguer strictement les faits matériellement constatés, les témoignages recueillis auprès de tiers et les simples suppositions non étayées."}]}, {"id": "fiche-e2", "num": "Étape 2", "titre": "Qualifier l'infraction", "paras": [{"li": "Rattachement légal : vérifier l'article du Grand Codex ou du Corpus Juriscivilis Imperialis (CJI) correspondant aux faits."}]}, {"id": "fiche-e3", "num": "Étape 3", "titre": "Informer le citoyen", "paras": [{"li": "Notification immédiate : exposer clairement et sans violence au citoyen les faits précis qui lui sont reprochés, le fondement légal (numéro d'article) ainsi que sa qualification."}]}, {"id": "fiche-e4", "num": "Étape 4", "titre": "Déterminer la procédure", "paras": [{"li": "Sanction directe sur place : pour les contraventions et délits relevant de la compétence de sanction directe de la Garde, notifier la formule tri-partite au prévenu (amende en septims OU heures de corvée OU heures d'emprisonnement direct en cellule de garde)."}, {"li": "Rétention et déféré : si l'infraction est un crime, ou en cas de refus d'exécution, de contestation véhémente ou de rébellion du prévenu, basculer immédiatement vers le placement en rétention conservatoire (24 h max) aux fins de présentation au magistrat."}]}, {"id": "fiche-e5", "num": "Étape 5", "titre": "Exécuter les mesures autorisées", "paras": [{"li": "Application de la sanction directe : recouvrer l'amende contre récépissé, engager la corvée sous surveillance ou placer le prévenu en cellule de garde pour la durée exacte fixée par le barème."}, {"li": "Saisie conservatoire : saisir immédiatement sur procès-verbal tout bien illicite, arme sous licence non justifiée, minerai pillé, gemme noire ou artefact occulte."}, {"li": "Rétention conservatoire : en cas de refus ou de crime, placer le contrevenant en cellule de garde (24 h max)."}]}, {"id": "fiche-e6", "num": "Étape 6", "titre": "Consigner l'intervention", "paras": [{"li": "Rédaction du procès-verbal : remplir un formulaire de verbalisation rapide en consignant l'identité du prévenu, les faits observés, l'article retenu, l'option choisie ou la mesure appliquée, les objets saisis et les suites données."}]}]}, {"titre": "Procédure de rétention conservatoire (24 h max)", "articles": [{"id": "fiche-retention", "num": "A.", "titre": "Cadre juridique et définition (CPIr, Art. 7-1)", "paras": ["La rétention conservatoire est une mesure administrative de contrainte temporaire d'une durée maximale de vingt-quatre (24) heures, exécutée dans les cellules de garde de la garnison. Elle ne constitue pas une peine définitive, mais une mesure de sûreté destinée à faire cesser le trouble et à garantir la mise à disposition du prévenu."]}, {"id": "fiche-retention-cas", "num": "B.", "titre": "Les 4 cas d'application obligatoires", "paras": [{"li": "1. Faits qualifiés de crime : tout crime (meurtre, nécromancie, complot, vol aggravé, profanation daedrique, etc.) entraîne l'arrestation immédiate et le placement sous écrou conservatoire dans l'attente du déféré devant le magistrat."}, {"li": "2. Refus d'exécution de la sanction directe : prévenu refusant de s'acquitter de l'amende forfaitaire, d'effectuer la corvée requise ou de purger les heures d'emprisonnement prévues."}, {"li": "3. Contestation véhémente, outrage ou rébellion : prévenu refusant de se soumettre au contrôle, faisant preuve de violence verbale/physique ou troublant gravement l'intervention de la Garde."}, {"li": "4. Risque de fuite ou impossibilité d'identifier le prévenu : individu sans domicile connu, voyageur clandestin ou étranger incapable de justifier de son identité et de garanties de représentation."}]}]}], "doc": "fiche"}];
